1550: async fn reenable_rebinds_without_restart() {
1551:     let Some(mut fx) = Fixture::spawn() else {
1552:         return;
1553:     };
1554:     let home = tempfile::tempdir().unwrap();
1555:     let rt = start_runtime(&home).await;
1556:     rt.register_declarative_spec(&fx.spec())
1557:         .await
1558:         .expect("register");
1559:     let pid = ProviderId::new(&fx.provider_id);
1560:     assert!(
1561:         join_session(&mut fx, &rt).await,
1562:         "先加入 session：{:?}\nsim log:\n{}",
1563:         fx.members(&rt),
1564:         fx.log_text()
1565:     );
1566:     rt.registry
1567:         .set_receptor_enabled(&ReceptorId::new(&fx.receptor_id), true)
1568:         .await
1569:         .expect("enable receptor");
1570: 
1571:     // 停用：離開 session、宣告撤回、來源解除登記。
1572:     rt.transition_provider(&pid, ProviderState::Disabled)
1573:         .await
1574:         .expect("disable");
1575:     // 20 秒是**測試機具**的等待上限（整個 workspace 並行時模擬器與 ack 都會變慢），
1576:     // 不是產品時序：停用本身是同步完成的。
1577:     assert!(
1578:         wait_until(Duration::from_secs(20), || {
1579:             let rt = rt.clone();
1580:             let device_id = fx.device_id.clone();
1581:             async move { presence_of(&rt, &device_id).is_none() }
1582:         })
1583:         .await,
1584:         "停用之後必須離開 session：{:?}\naudits: {:?}\nsim log:\n{}",
1585:         fx.members(&rt),
1586:         rt.store
1587:             .audit_tail(400)
1588:             .unwrap_or_default()
1589:             .iter()
1590:             .filter_map(|r| r["kind"].as_str().map(str::to_string))
1591:             .collect::<Vec<_>>(),
1592:         fx.log_text()
1593:     );
1594:     assert_eq!(
1595:         rt.declarative_lifecycle(&fx.provider_id),
1596:         Some(DeclarativeLifecycle::Unbound {
1597:             reason: UnboundReason::Disabled
1598:         }),
1599:         "停用的原因必須說得出來"
1600:     );
1601: 
1602:     // 啟用：狀態誠實地退到 disconnected，背景重新綁定。
1603:     let back = rt
1604:         .transition_provider(&pid, ProviderState::Available)
1605:         .await
1606:         .expect("re-enable");
1607:     assert_eq!(
1608:         back.state,
1609:         ProviderState::Disconnected,
1610:         "還沒握上手就不得說可用：{back:?}"
1611:     );
1612: 
1613:     assert!(
1614:         wait_until(Duration::from_secs(25), || {
1615:             let rt = rt.clone();
1616:             let pid = pid.clone();
1617:             async move {
1618:                 rt.declarative_lifecycle(pid.as_str()) == Some(DeclarativeLifecycle::Bound)
1619:                     && rt
1620:                         .list_providers()
1621:                         .await
1622:                         .into_iter()
1623:                         .any(|p| p.identity.id == pid && p.state == ProviderState::Available)
1624:             }
1625:         })
1626:         .await,
1627:         "同一個行程裡就要重新握上手並收斂成 available；sim log:\n{}",
1628:         fx.log_text()
1629:     );
1630:     let rebound = audit_rows(&rt, "provider.rebound");
1631:     assert_eq!(rebound.len(), 1, "{rebound:?}");
1632:     assert_eq!(rebound[0]["detail"]["handshake"], json!("ready"));
