267: async fn wait_until<F, Fut>(timeout: Duration, mut probe: F) -> bool
268: where
269:     F: FnMut() -> Fut,
270:     Fut: std::future::Future<Output = bool>,
271: {
272:     let deadline = Instant::now() + timeout;
273:     loop {
274:         if probe().await {
275:             return true;
276:         }
277:         if Instant::now() >= deadline {
278:             return false;
279:         }
280:         tokio::time::sleep(Duration::from_millis(100)).await;
281:     }
282: }

