800:     let handshake = if channels.is_empty() {
801:         // 沒有裝置線（純 HTTP adapter）：沒有握手可等。誠實：這不是「握手成功」。
802:         "none"
803:     } else {
804:         let deadline = tokio::time::Instant::now() + REBIND_HANDSHAKE_BUDGET;
805:         loop {
806:             if channels.iter().all(|c| c.handshake_ready()) {
807:                 break "ready";
808:             }
809:             if channels
810:                 .iter()
811:                 .any(|c| matches!(c.readiness(), LinkReadiness::Closed))
812:             {
813:                 return Err(RebindStop::Failed(
814:                     "a device link was closed while the rebind was waiting for its handshake"
815:                         .into(),
816:                 ));
817:             }
818:             if tokio::time::Instant::now() >= deadline {
819:                 return Err(RebindStop::Failed(format!(
820:                     "the device did not complete its hello/pairing handshake within {} s; it is \
821:                      NOT connected",
822:                     REBIND_HANDSHAKE_BUDGET.as_secs()
823:                 )));
824:             }
825:             tokio::time::sleep(REBIND_POLL).await;
826:         }
827:     };
