830:     let Some(rt) = upgrade(weak) else {
831:         return Err(RebindStop::Superseded("the runtime is gone".into()));
832:     };
833:     {
834:         // 綁定先成立、狀態才敢說可用，而且**在同一把鎖裡**：兩者之間插進一次
835:         // 停用，就會讓「已停用」與「可用」同時成立。
836:         let _serialized = rt.providers.lock_provider(&id).await;
