179:     /// 握手成立：留一次身分強度稽核，並讓已經是成員的裝置回到 online。
180:     async fn note_ready(&self, rt: &Runtime) {
181:         if !self.announced_identity.swap(true, Ordering::SeqCst) {
182:             let _ = rt.store.audit(
183:                 "aip.device-channel-ready",
184:                 "runtime",
185:                 &json!({
186:                     "providerId": self.provider_id,
187:                     "deviceId": self.channel.expected_device_id(),
188:                     "transport": self.channel.transport_label(),
189:                     // 誠實：這條線的身分比已配對 iPhone 弱，稽核必須說得出來。
190:                     "identityStrength": IDENTITY_STRENGTH_DEVICE_LINK,
191:                     "pairingUnverified": self.channel.pairing_unverified(),
192:                 }),
193:             );
194:         }
195:         self.announced_reconnecting.store(false, Ordering::SeqCst);
196:         // 出站登記：從這一刻起，別的成員造成的 shared state 變更才送得到這台
197:         // 裝置。冪等（同一台裝置重複握手只是覆蓋同一個鍵）。
198:         rt.register_device_outbound(
199:             &self.channel.expected_device_id(),
200:             Arc::new(DeclarativeOutbound {
201:                 channel: self.channel.clone(),
202:                 provider_id: self.provider_id.clone(),
203:             }),
204:         );
205:         let party = self.party();
206:         if rt.character_session_is_member(&party) {
207:             rt.character_session_presence(&party, Presence::Online)
208:                 .await;
209:         }
210:         // 這條線真的握上手了：如果 provider 還停在「重新連線中」
211:         // （`Disconnected`），現在才是把它收斂成 `Available` 的時刻。
212:         // 只認 `Disconnected` 這一個入口——握手不得冒充人類的啟用決定。
213:         rt.converge_provider_after_link_ready(&interaction_core::ProviderId::new(
214:             &self.provider_id,
215:         ))
216:         .await;
217:     }

1500:     pub(crate) async fn converge_provider_after_link_ready(&self, id: &ProviderId) {
1501:         use crate::declarative_lifecycle::LinkReadyOutcome;
1502:         let _serialized = self.providers.lock_provider(id).await;
1503:         // 撤銷／停用的決定跨重啟有效：store 說它是關的，就沒有任何背景握手
1504:         // 可以把它打開。
1505:         if let Some(reason) = self.provider_off_reason(id) {
1506:             let _ = self.store.audit(
1507:                 "provider.link-ready-refused",
1508:                 "runtime",
1509:                 &serde_json::json!({
1510:                     "providerId": id.as_str(),
1511:                     "reason": format!("this device is still marked off ({reason})"),
1512:                 }),
1513:             );
1514:             return;
1515:         }
1516:         let outcome = self.note_declarative_link_ready(id.as_str());
1517:         let (established, recovered) = match &outcome {
1518:             LinkReadyOutcome::Refused { lifecycle } => {
1519:                 let _ = self.store.audit(
1520:                     "provider.link-ready-refused",
1521:                     "runtime",
1522:                     &serde_json::json!({
1523:                         "providerId": id.as_str(),
1524:                         "lifecycle": lifecycle,
1525:                         "reason": "a late handshake never revives a binding the human took down",
1526:                     }),
1527:                 );
1528:                 return;
1529:             }
1530:             // 綁定表對它一無所知：維持既有行為（只收斂狀態），但也不假裝
1531:             // 「綁定成立了」——失敗說明不得在這條路徑上被抹掉。
1532:             LinkReadyOutcome::NotTracked => (false, false),
1533:             LinkReadyOutcome::AlreadyBound | LinkReadyOutcome::Committed { .. } => (true, false),
1534:             LinkReadyOutcome::RecoveredAfterFailure => (true, true),
1535:         };
1536:         self.converge_provider_state_locked(id, established, recovered)
1537:             .await;
1538:         if recovered {
1539:             // 這一輪 rebind 的第 7 步已經把「人類先前手動關掉的受器」套用回去
1540:             // 了（只是握手晚了一步）；紀錄留著的話，之後一次由**斷線**觸發的
1541:             // 重新綁定會拿一份過期的名單去關掉人類早就重新打開的受器。
1542:             self.clear_declarative_human_disabled(id.as_str());
1543:         }
1544:     }
